void testFunction(Queue Q)
{
    Stack S;
    int item;

    while (!Q.isEmpty())
    {
        item = Q.peekFront();
        Q.dequeue();
        S.push(item);
    }
    // CHECK POINT 1
    while (!S.isEmpty())
    {
        item = S.peek();
        S.pop();
        Q.enqueue(item);
    }
    // CHECK POINT 2
}

